import subprocess, sys, json
EXE="/workspace/executable"
FUNCS=["japanese","hiragana","katakana","kana","kanji","greek"]
def probe(cps, funcs=FUNCS, chunk=48):
    """returns dict cp -> dict func->bool"""
    res={}
    for i in range(0,len(cps),chunk):
        part=cps[i:i+chunk]
        cols=[]
        for cp in part:
            ch=chr(cp)
            for f in funcs:
                cols.append("%s('%s')"%(f,ch))
        q=", ".join(cols)
        p=subprocess.run([EXE,q],cwd="/tmp/sf/one",capture_output=True,text=True)
        if p.returncode!=0:
            print("ERR rc=%d %r"%(p.returncode,p.stderr[:300]),file=sys.stderr); continue
        vals=p.stdout.rstrip("\n").split("\t")
        if len(vals)!=len(part)*len(funcs):
            print("MISMATCH got %d want %d for cp %04X.. : %r"%(len(vals),len(part)*len(funcs),part[0],vals[:10]),file=sys.stderr); continue
        k=0
        for cp in part:
            d={}
            for f in funcs:
                d[f]= vals[k]=="true"
                k+=1
            res[cp]=d
    return res
def ranges(cps_true):
    out=[]
    for cp in sorted(cps_true):
        if out and out[-1][1]==cp-1: out[-1][1]=cp
        else: out.append([cp,cp])
    return out
def fmt(rs):
    return ", ".join("U+%04X"%a if a==b else "U+%04X-U+%04X"%(a,b) for a,b in rs)
if __name__=="__main__":
    lo=int(sys.argv[1],16); hi=int(sys.argv[2],16)
    cps=[c for c in range(lo,hi+1) if not (0<=c<0x20) and c not in (0x27,) and not (0xD800<=c<=0xDFFF)]
    r=probe(cps)
    for f in FUNCS:
        t=[cp for cp in r if r[cp][f]]
        if t: print("%-10s %s"%(f,fmt(ranges(t))))
        else: print("%-10s (none)"%f)
